export function flowRelease(verifiedSourceIds,baseNodeIds){
  const existing=new Set(baseNodeIds),nodes=flowNodes.filter(n=>!existing.has(n.id)&&n.sourceIds.every(id=>verifiedSourceIds.has(id))).map(n=>({...n}));
  const ids=new Set([...existing,...nodes.map(n=>n.id)]);
  const edges=flowEdges.filter(e=>e.sourceIds.every(id=>verifiedSourceIds.has(id))&&ids.has(e.source)&&ids.has(e.target));
  return {nodes,edges,complete:flowSources.every(s=>verifiedSourceIds.has(s.id))};
}
